/*
 * ONLINE COURSE 07 — MODULAR SKILL BUILDER
 * Pure Canvas 2D | one scene | seamless 25-second loop | 4K UHD | 60 fps.
 * Time is supplied in SECONDS. No DOM, scheduler, libraries, or outside assets.
 * Static background. No glow, blur, shadows, perspective, or elastic scaling.
 * Export target: 100,000,000 bits/second (100 Mbps).
 * The host encoder must apply and verify the bitrate; Canvas draws pixels.
 */
var animationConfig = {
  duration: 25, sceneCount: 1, width: 3840, height: 2160, fps: 60,
  bitrate: 100000000, videoBitsPerSecond: 100000000,
  minVideoBitrate: 100000000, loop: true
};

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const u = sceneProgress;
  const C = { ink: '#294B58', muted: '#6F8E97', teal: '#478F88', blue: '#648FAE', slate: '#748BA4', ochre: '#AB936B' };
  // Edge order: top, right, bottom, left. +1 is a tab; -1 a matching recess.
  const pieces = [
    { sx: -1, sy: -1, turn: Math.PI / 2, edges: [0, 1, 1, 0], fill: '#E4F0EC', accent: C.teal, title: 'VIDEO', sub: 'MODULE 01' },
    { sx: 1, sy: -1, turn: -Math.PI / 2, edges: [0, 0, 1, -1], fill: '#BED7D3', accent: C.blue, title: 'READ', sub: 'MODULE 02' },
    { sx: -1, sy: 1, turn: -Math.PI / 2, edges: [-1, 1, 0, 0], fill: '#B9CEDA', accent: C.slate, title: 'PRACTICE', sub: 'MODULE 03' },
    { sx: 1, sy: 1, turn: Math.PI / 2, edges: [-1, 0, 0, -1], fill: '#D6DED2', accent: C.ochre, title: 'COMPLETE', sub: 'MODULE 04' }
  ];

  function clamp(v) { return Math.max(0, Math.min(1, v)); }
  function smooth(a, b, v) {
    const x = clamp((v - a) / (b - a));
    return x * x * x * (x * (x * 6 - 15) + 10);
  }
  function mix(a, b, v) { return a + (b - a) * v; }
  function rr(x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r); ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h); ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r); ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(x, y, w, h, r, fill, stroke, lw) {
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function line(pts, color, lw, alpha) {
    ctx.save(); if (alpha !== undefined) ctx.globalAlpha *= alpha;
    ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
    for (let j = 1; j < pts.length; j++) ctx.lineTo(pts[j][0], pts[j][1]);
    ctx.strokeStyle = color; ctx.lineWidth = lw || 2; ctx.stroke(); ctx.restore();
  }
  function text(s, x, y, size, color, weight, align) {
    const fw = weight >= 650 ? 700 : weight >= 550 ? 600 : 500;
    ctx.font = fw + ' ' + size + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color; ctx.fillText(s, x, y);
  }
  function check(x, y, size, color) {
    line([[x - size * .45, y], [x - size * .1, y + size * .31], [x + size * .49, y - size * .35]], color, 2.6);
  }

  // Matching profiles are monotone along the edge. Their rounded tabs can
  // enter the recesses in 2D without undercuts or silhouette intersections.
  // The assembled grid retains a 24-unit gap between the base edges.
  function piecePath(edges, targetContext) {
    const p = targetContext || ctx, H = 106, R = 16;
    function profile(cx, cy, tx, ty, nx, ny, sign) {
      if (!sign) return;
      function pt(s, d) { return [cx + tx * s + nx * d * sign, cy + ty * s + ny * d * sign]; }
      const a = pt(-34, 0); p.lineTo(a[0], a[1]);
      const groups = [
        [-25, 0, -22, 2, -18, 10],
        [-14, 18, -14, 36, 0, 36],
        [14, 36, 14, 18, 18, 10],
        [22, 2, 25, 0, 34, 0]
      ];
      for (const g of groups) {
        const a = pt(g[0], g[1]), b = pt(g[2], g[3]), c = pt(g[4], g[5]);
        p.bezierCurveTo(a[0], a[1], b[0], b[1], c[0], c[1]);
      }
    }
    p.beginPath(); p.moveTo(-H + R, -H);
    profile(0, -H, 1, 0, 0, -1, edges[0]); p.lineTo(H - R, -H); p.quadraticCurveTo(H, -H, H, -H + R);
    profile(H, 0, 0, 1, 1, 0, edges[1]); p.lineTo(H, H - R); p.quadraticCurveTo(H, H, H - R, H);
    profile(0, H, -1, 0, 0, 1, edges[2]); p.lineTo(-H + R, H); p.quadraticCurveTo(-H, H, -H, H - R);
    profile(-H, 0, 0, -1, -1, 0, edges[3]); p.lineTo(-H, -H + R); p.quadraticCurveTo(-H, -H, -H + R, -H);
    p.closePath();
  }
  function moduleGlyph(id, color) {
    if (id === 0) {
      box(-23, -27, 46, 34, 6, null, color, 2.4);
      ctx.beginPath(); ctx.moveTo(-5, -19); ctx.lineTo(10, -10); ctx.lineTo(-5, -1); ctx.closePath();
      ctx.fillStyle = color; ctx.fill();
    } else if (id === 1) {
      ctx.beginPath(); ctx.moveTo(0, -23);
      ctx.quadraticCurveTo(-10, -30, -22, -24); ctx.lineTo(-22, 5);
      ctx.quadraticCurveTo(-10, -1, 0, 7); ctx.quadraticCurveTo(10, -1, 22, 5);
      ctx.lineTo(22, -24); ctx.quadraticCurveTo(10, -30, 0, -23); ctx.closePath();
      ctx.strokeStyle = color; ctx.lineWidth = 2.4; ctx.stroke();
      line([[0, -23], [0, 7]], color, 1.9);
      line([[-15, -15], [-7, -13]], color, 1.6); line([[7, -13], [15, -15]], color, 1.6);
    } else if (id === 2) {
      line([[-10, -26], [-24, -10], [-10, 6]], color, 2.5);
      line([[10, -26], [24, -10], [10, 6]], color, 2.5);
      line([[4, -28], [-4, 8]], color, 2.3);
    } else {
      box(-20, -31, 40, 43, 7, null, color, 2.4); check(0, -9, 28, color);
    }
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowColor = 'transparent'; ctx.filter = 'none';
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
  const bg = ctx.createLinearGradient(0, height, width, 0);
  bg.addColorStop(0, '#183E49'); bg.addColorStop(.52, '#3C6370'); bg.addColorStop(1, '#819CA0');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);
  ctx.beginPath(); ctx.moveTo(0, height * .15);
  ctx.bezierCurveTo(width * .24, height * .43, width * .30, height * .02, width * .62, 0);
  ctx.lineTo(0, 0); ctx.closePath(); ctx.fillStyle = 'rgba(209,233,230,0.045)'; ctx.fill();
  ctx.beginPath(); ctx.moveTo(width * .57, height);
  ctx.bezierCurveTo(width * .77, height * .64, width * .90, height * .79, width, height * .55);
  ctx.lineTo(width, height); ctx.closePath(); ctx.fillStyle = 'rgba(16,48,61,0.11)'; ctx.fill();
  ctx.translate(width / 2, height * .495); ctx.scale(scale * 1.15, scale * 1.15);
  line([[-420, 397], [-382, 397]], '#9CB9BD', 2, .65);
  line([[-363, 397], [363, 397]], '#9CB9BD', 2, .65);
  line([[382, 397], [420, 397]], '#9CB9BD', 2, .65);

  const connected = smooth(.55, .615, u) * (1 - smooth(.765, .80, u));
  ctx.save(); ctx.globalAlpha *= connected;
  const arms = [[0, -62, 0, -12], [62, 0, 12, 0], [0, 62, 0, 12], [-62, 0, -12, 0]];
  for (let j = 0; j < 4; j++) {
    const a = arms[j]; line([[a[0], a[1]], [a[2], a[3]]], '#A1BFBD', 1.7);
    const v = ((u * 4 - j * .25) % 1 + 1) % 1;
    ctx.save(); ctx.globalAlpha *= Math.pow(Math.sin(v * Math.PI), 2);
    circle(mix(a[0], a[2], v), mix(a[1], a[3], v), 2.8, '#E6F2EB'); ctx.restore();
  }
  circle(0, 0, 5, '#B9D6D1', '#DDEBE6', 1.2); ctx.restore();

  for (let j = 0; j < pieces.length; j++) {
    const piece = pieces[j];
    const join = smooth(.20 + j * .08, .35 + j * .08, u);
    const release = smooth(.80 + j * .005, .905 + j * .005, u);
    const offset = 100 * (1 - join + release);
    const x = piece.sx * (118 + offset), y = piece.sy * (118 + offset);
    const angle = piece.turn * (1 - smooth(.01 + j * .02, .12 + j * .02, u) + smooth(.925, 1, u));
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    piecePath(piece.edges, ctx); ctx.fillStyle = piece.fill; ctx.fill();
    ctx.strokeStyle = C.ink; ctx.lineWidth = 3; ctx.stroke();
    circle(-72, -72, 9, '#EDF5F2', '#8DAEAF', 1.3);
    text('0' + (j + 1), -72, -69, 7, C.muted, 700, 'center');
    circle(0, -10, 40, '#F5FAF6', '#93B1B5', 1.6);
    moduleGlyph(j, piece.accent);
    box(-27, 35, 54, 4, 2, '#A0BBB9', null);
    const v = ((u * 4 - j * .17) % 1 + 1) % 1;
    ctx.save(); ctx.globalAlpha *= Math.pow(Math.sin(v * Math.PI), 2);
    box(-27 + 36 * v, 35, 18, 4, 2, piece.accent, null); ctx.restore();
    text(piece.title, 0, 61, 12, C.ink, 700, 'center');
    text(piece.sub, 0, 79, 8, C.muted, 600, 'center');
    ctx.restore();
  }
  ctx.restore();
}

draw.duration = 25;
draw.fps = 60;
draw.exportSettings = animationConfig;

/*
 * ONLINE COURSE 08 — LEARNING ROADMAP
 * Pure Canvas 2D | one scene | seamless 25-second loop | 4K UHD | 60 fps.
 * Time is supplied in SECONDS. No DOM, scheduler, libraries, or outside assets.
 * Static background. No glow, blur, or perspective. Closed, noncrossing route.
 * Export target: 100,000,000 bits/second (100 Mbps).
 * The host encoder must apply and verify this bitrate; Canvas draws pixels.
 */
var animationConfig = {
  duration: 25, sceneCount: 1, width: 3840, height: 2160, fps: 60,
  bitrate: 100000000, videoBitsPerSecond: 100000000,
  minVideoBitrate: 100000000, loop: true
};

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const u = sceneProgress;
  const C = { ink: '#36516A', muted: '#8499AA', line: '#C8D8E4', paper: '#FAFCFF', blue: '#6B8DBA', teal: '#609F99', ochre: '#BB986F' };
  const accents = [C.blue, C.teal, C.ochre];

  function clamp(v) { return Math.max(0, Math.min(1, v)); }
  function smooth(a, b, v) {
    const x = clamp((v - a) / (b - a));
    return x * x * x * (x * (x * 6 - 15) + 10);
  }
  function mix(a, b, v) { return a + (b - a) * v; }
  function colorMix(a, b, v) {
    const n = parseInt(a.slice(1), 16), m = parseInt(b.slice(1), 16);
    return 'rgb(' + Math.round(mix((n >> 16) & 255, (m >> 16) & 255, v)) + ',' + Math.round(mix((n >> 8) & 255, (m >> 8) & 255, v)) + ',' + Math.round(mix(n & 255, m & 255, v)) + ')';
  }
  function rr(x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r); ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h); ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r); ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(x, y, w, h, r, fill, stroke, lw) {
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function line(pts, color, lw, alpha) {
    ctx.save(); if (alpha !== undefined) ctx.globalAlpha *= alpha;
    ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
    for (let j = 1; j < pts.length; j++) ctx.lineTo(pts[j][0], pts[j][1]);
    ctx.strokeStyle = color; ctx.lineWidth = lw || 2; ctx.stroke(); ctx.restore();
  }
  function text(s, x, y, size, color, weight, align) {
    const fw = weight >= 650 ? 700 : weight >= 550 ? 600 : 500;
    ctx.font = fw + ' ' + size + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color; ctx.fillText(s, x, y);
  }
  function check(x, y, size, progress, color) {
    if (progress <= 0) return;
    const p = clamp(progress), split = .42;
    const a = [x - size * .45, y], b = [x - size * .1, y + size * .31], c = [x + size * .49, y - size * .35];
    ctx.beginPath(); ctx.moveTo(a[0], a[1]);
    if (p < split) ctx.lineTo(mix(a[0], b[0], p / split), mix(a[1], b[1], p / split));
    else { ctx.lineTo(b[0], b[1]); ctx.lineTo(mix(b[0], c[0], (p - split) / (1 - split)), mix(b[1], c[1], (p - split) / (1 - split))); }
    ctx.strokeStyle = color; ctx.lineWidth = 1.8; ctx.stroke();
  }
  function L(x0, y0, x1, y1) { return { kind: 'L', x0: x0, y0: y0, x1: x1, y1: y1, length: Math.hypot(x1 - x0, y1 - y0) }; }
  function A(cx, cy, r, a0, a1) { return { kind: 'A', cx: cx, cy: cy, r: r, a0: a0, a1: a1, length: r * Math.abs(a1 - a0) }; }
  const route = [
    L(-275, -180, 275, -180), A(275, -95, 85, -Math.PI / 2, Math.PI / 2),
    L(275, -10, -275, -10), A(-275, 75, 85, -Math.PI / 2, -Math.PI * 1.5),
    L(-275, 160, 275, 160), A(275, 222.5, 62.5, -Math.PI / 2, Math.PI / 2),
    L(275, 285, -365, 285), A(-365, 200, 85, Math.PI / 2, Math.PI),
    L(-450, 200, -450, -95), A(-365, -95, 85, Math.PI, Math.PI * 1.5),
    L(-365, -180, -275, -180)
  ];
  let routeLength = 0;
  for (const part of route) { part.start = routeLength; routeLength += part.length; }
  function routePath() {
    ctx.beginPath(); ctx.moveTo(-275, -180);
    for (const p of route) {
      if (p.kind === 'L') ctx.lineTo(p.x1, p.y1);
      else ctx.arc(p.cx, p.cy, p.r, p.a0, p.a1, p.a1 < p.a0);
    }
    ctx.closePath();
  }
  function pointAt(distance) {
    const d = ((distance % routeLength) + routeLength) % routeLength;
    let p = route[route.length - 1];
    for (const candidate of route) if (d <= candidate.start + candidate.length) { p = candidate; break; }
    const f = clamp((d - p.start) / p.length);
    if (p.kind === 'L') return { x: mix(p.x0, p.x1, f), y: mix(p.y0, p.y1, f), tx: (p.x1 - p.x0) / p.length, ty: (p.y1 - p.y0) / p.length };
    const a = mix(p.a0, p.a1, f), sign = p.a1 > p.a0 ? 1 : -1;
    return { x: p.cx + Math.cos(a) * p.r, y: p.cy + Math.sin(a) * p.r, tx: -Math.sin(a) * sign, ty: Math.cos(a) * sign };
  }
  // Positive, periodic speed: slow through the learning steps, faster on the
  // return lane. Velocity and acceleration agree on both sides of the seam.
  const travel = routeLength * (u + .45 / TAU * (Math.sin(phase + Math.PI * .3) - Math.sin(Math.PI * .3)));
  const token = pointAt(travel);
  const gates = [
    { s: 170, title: 'WATCH', color: C.blue },
    { s: route[2].start + 175, title: 'READ', color: C.teal },
    { s: route[4].start + 170, title: 'PRACTICE', color: C.ochre }
  ];
  function completed(distance) {
    return smooth(distance + 12, distance + 78, travel) * (1 - smooth(routeLength - 300, routeLength - 80, travel));
  }
  function drawGate(g, id) {
    const p = pointAt(g.s), theta = Math.atan2(p.ty, p.tx);
    const difference = Math.abs(travel - g.s);
    const separation = Math.min(difference, routeLength - difference);
    const opening = 1 - smooth(55, 160, separation);
    const topAngle = (1 - opening) * Math.PI / 2;
    const bottomAngle = -Math.PI / 2 - opening * Math.PI / 2;
    ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(theta);
    line([[0, -35], [27 * Math.cos(topAngle), -35 + 27 * Math.sin(topAngle)]], g.color, 6);
    line([[0, 35], [27 * Math.cos(bottomAngle), 35 + 27 * Math.sin(bottomAngle)]], g.color, 6);
    circle(0, -35, 6.5, '#F9FCFF', g.color, 2);
    circle(0, 35, 6.5, '#F9FCFF', g.color, 2);
    ctx.restore();
    const done = completed(g.s), labelY = p.y + 76;
    box(p.x - 73, labelY - 18, 146, 36, 10, '#F6FAFD', colorMix('#D0DDE9', g.color, done * .5), 1.4);
    circle(p.x - 54, labelY, 9, '#FDFEFF', g.color, 1.2);
    text('0' + (id + 1), p.x - 54, labelY + 3, 7, C.muted, 700, 'center');
    text(g.title, p.x - 35, labelY + 4, 10, C.ink, 700);
    circle(p.x + 56, labelY, 6, '#FCFEFF', colorMix('#CCDAE6', g.color, done), 1.1);
    check(p.x + 56, labelY, 7, done, g.color);
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowColor = 'transparent'; ctx.filter = 'none';
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
  const bg = ctx.createLinearGradient(0, height, width, 0);
  bg.addColorStop(0, '#DCE8F0'); bg.addColorStop(.52, '#EAF0F5'); bg.addColorStop(1, '#DDE4EF');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);
  ctx.beginPath(); ctx.moveTo(0, height * .16);
  ctx.bezierCurveTo(width * .23, height * .43, width * .31, height * .02, width * .61, 0);
  ctx.lineTo(0, 0); ctx.closePath(); ctx.fillStyle = 'rgba(143,169,191,0.08)'; ctx.fill();
  ctx.beginPath(); ctx.moveTo(width * .58, height);
  ctx.bezierCurveTo(width * .77, height * .65, width * .91, height * .80, width, height * .55);
  ctx.lineTo(width, height); ctx.closePath(); ctx.fillStyle = 'rgba(148,162,187,0.075)'; ctx.fill();
  ctx.translate(width / 2, height * .48); ctx.scale(scale, scale);
  line([[-584, 396], [-546, 396]], '#A9BDCA', 2);
  line([[-527, 396], [527, 396]], '#A9BDCA', 2);
  line([[546, 396], [584, 396]], '#A9BDCA', 2);
  box(-528, -344, 1056, 704, 27, C.paper, C.ink, 3.6);
  ctx.save(); rr(-526, -342, 1052, 700, 25); ctx.clip();
  ctx.fillStyle = '#DEE8F4'; ctx.fillRect(-528, -344, 1056, 66);
  line([[-528, -278], [528, -278]], '#C3D3E3', 1.5); ctx.restore();
  text('LEARNING ROADMAP', -484, -303, 20, C.ink, 700);
  text('STEP BY STEP', 484, -304, 10, C.muted, 700, 'right');

  routePath(); ctx.strokeStyle = '#B7CAD9'; ctx.lineWidth = 32; ctx.stroke();
  routePath(); ctx.strokeStyle = '#E8F1F6'; ctx.lineWidth = 27; ctx.stroke();
  ctx.save(); ctx.setLineDash([4, 11]); routePath(); ctx.strokeStyle = '#BDCEDC'; ctx.lineWidth = 1.5; ctx.stroke(); ctx.restore();
  box(-319, -254, 88, 29, 9, '#EDF4FA', '#CCDBE9', 1.2);
  text('START', -275, -235, 10, C.muted, 700, 'center');
  text('NEXT LESSON', 140, 252, 9, C.muted, 700, 'center');
  for (let j = 0; j < gates.length; j++) drawGate(gates[j], j);

  box(373, 92, 116, 125, 13, '#F1F7F9', '#CADBE5', 1.4);
  text('GOAL', 431, 109, 9, C.muted, 700, 'center');
  const goalS = route[4].start + route[4].length;
  const goalDone = completed(goalS);
  line([[404, 122], [404, 179]], C.ink, 2.2);
  line([[398, 179], [410, 179]], C.ink, 2.2);
  const wave = 3.5 * Math.sin(phase * 5);
  ctx.beginPath(); ctx.moveTo(404, 123);
  ctx.bezierCurveTo(418, 123 - wave, 433, 123 + wave, 447, 123);
