/*
 * 09 - CLOUD COURSE LIBRARY
 * Pure Canvas 2D. time is in SECONDS. One continuous 25-second scene.
 * Intended master: 3840 x 2160, 60 fps, seamless loop.
 * The background is static. No glow, blur, shadows, images or external assets.
 * Apply the 100,000,000-bit/s settings in the host VIDEO ENCODER;
 * drawing pixels alone cannot set or verify an encoded video's bitrate.
 */
var animationConfig = {
  duration: 25, sceneCount: 1, width: 3840, height: 2160, fps: 60,
  bitrate: 100000000, videoBitsPerSecond: 100000000,
  minVideoBitrate: 100000000, loop: true
};

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0)) return;
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const u = sceneProgress;
  const ink = '#263D62';
  const lanes = [
    { x: -232, title: 'VIDEO', tint: '#E5EDF9', color: '#567EB5' },
    { x: 0, title: 'READ', tint: '#E8E6F5', color: '#8175B0' },
    { x: 232, title: 'AUDIO', tint: '#DEEEE9', color: '#4E948D' }
  ];

  // C2-continuous quintic Hermite interpolation for smooth acceleration/deceleration
  function smooth(a, b, value) {
    const x = Math.max(0, Math.min(1, (value - a) / (b - a)));
    return x * x * x * (x * (x * 6 - 15) + 10);
  }

  function rr(x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function line(x1, y1, x2, y2, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function text(label, x, y, size, color, weight, align) {
    const fw = weight >= 650 ? 700 : weight >= 550 ? 600 : 500;
    ctx.font = fw + ' ' + size + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(label, x, y);
  }

  // Exact symmetric circular-lobe cloud silhouette with a flat horizontal base at y = -134
  const cloudLobes = [
    { x: -262, y: -198, r: 64 },
    { x: -152, y: -254, r: 86 },
    { x: 0, y: -271, r: 104 },
    { x: 152, y: -254, r: 86 },
    { x: 262, y: -198, r: 64 }
  ];
  const cloudArcs = [];
  for (let i = 0; i < cloudLobes.length; i++) {
    let startAngle = Math.PI * 0.5;
    let endAngle = Math.PI * 0.5;
    if (i > 0) {
      const prev = cloudLobes[i - 1];
      const curr = cloudLobes[i];
      const dx = prev.x - curr.x;
      const dy = prev.y - curr.y;
      const d = Math.hypot(dx, dy);
      const base = Math.atan2(dy, dx);
      const offset = Math.acos((curr.r * curr.r + d * d - prev.r * prev.r) / (2 * curr.r * d));
      startAngle = base + offset;
    }
    if (i < cloudLobes.length - 1) {
      const curr = cloudLobes[i];
      const next = cloudLobes[i + 1];
      const dx = next.x - curr.x;
      const dy = next.y - curr.y;
      const d = Math.hypot(dx, dy);
      const base = Math.atan2(dy, dx);
      const offset = Math.acos((curr.r * curr.r + d * d - next.r * next.r) / (2 * curr.r * d));
      endAngle = base - offset;
    }
    cloudArcs.push({
      x: cloudLobes[i].x,
      y: cloudLobes[i].y,
      r: cloudLobes[i].r,
      start: startAngle,
      end: endAngle
    });
