  function cloudPath() {
    ctx.beginPath();
    ctx.moveTo(cloudArcs[0].x, -134);
    for (let i = 0; i < cloudArcs.length; i++) {
      const a = cloudArcs[i];
      ctx.arc(a.x, a.y, a.r, a.start, a.end, false);
    }
    ctx.closePath();
  }

  function check(x, y, p, color, size) {
    if (p <= 0) return;
    const pts = [
      [x - size * 0.44, y + size * 0.02],
      [x - size * 0.10, y + size * 0.34],
      [x + size * 0.48, y - size * 0.32]
    ];
    const lengths = [
      Math.hypot(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]),
      Math.hypot(pts[2][0] - pts[1][0], pts[2][1] - pts[1][1])
    ];
    let left = (lengths[0] + lengths[1]) * p;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 0; i < 2; i++) {
      const f = Math.min(1, left / lengths[i]);
      ctx.lineTo(
        pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f,
        pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f
      );
      left -= lengths[i];
      if (left <= 0) break;
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = 2.4;
    ctx.stroke();
