  function glyph(index, x, y, amount, color, live, small) {
    if (amount <= 0) return;
    ctx.save();
    ctx.translate(x, y);
    if (small) ctx.scale(0.56, 0.56);
    ctx.globalAlpha *= amount;
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 2.6;

