      ctx.lineTo(-20, -16);
      ctx.lineTo(-20, 16);
      ctx.lineTo(-11, 16);
      ctx.moveTo(11, -16);
      ctx.lineTo(20, -16);
      ctx.lineTo(20, 16);
      ctx.lineTo(11, 16);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(-5.5, -9.5);
      ctx.lineTo(9.5, 0);
      ctx.lineTo(-5.5, 9.5);
      ctx.closePath();
      ctx.fill();
