      // Clean document page with evenly spaced text lines
      rr(-16, -20, 32, 40, 5);
      ctx.stroke();
      const widths = [18, 18, 12];
      for (let k = 0; k < 3; k++) {
        const f = smooth(k * 0.14, 0.68 + k * 0.14, amount);
        if (f > 0) {
          const ly = -9 + k * 9;
          line(-9, ly, -9 + widths[k] * f, ly, color, 2.5);
