  ctx.beginPath();
  ctx.moveTo(0, height * 0.09);
  ctx.bezierCurveTo(width * 0.30, height * 0.48, width * 0.60, -height * 0.15, width, height * 0.21);
  ctx.lineTo(width, 0);
  ctx.lineTo(0, 0);
