  ctx.fill();

  ctx.fillStyle = 'rgba(156,177,210,0.075)';
  ctx.beginPath();
  ctx.moveTo(0, height * 0.77);
  ctx.bezierCurveTo(width * 0.32, height * 0.46, width * 0.68, height * 1.09, width, height * 0.72);
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();
  ctx.fill();

  ctx.translate(width / 2, height * 0.50);
  ctx.scale(scale, scale);

  // 1. PARALLEL DATA CHANNELS & UPSTREAM PACKETS
  const channelTopY = -134;
  const channelBottomY = 156;
  for (let j = 0; j < lanes.length; j++) {
    const lane = lanes[j];
    line(lane.x, channelTopY, lane.x, channelBottomY, '#B2BDD4', 2.2);

    // Subtle carrier pulse in the upper channel gap (between Cloud and Staging Card)
