        ctx.save();
        ctx.globalAlpha = opacity;
        rr(lane.x - 16, packetY - 11, 32, 22, 6);
        ctx.fillStyle = lane.tint;
        ctx.fill();
        ctx.strokeStyle = lane.color;
        ctx.lineWidth = 1.8;
        ctx.stroke();
