    ctx.arc(lanes[j].x, channelTopY, 4.5, 0, TAU);
    ctx.fillStyle = '#FFFFFF';
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 2.2;
    ctx.stroke();
