    const lane = lanes[j];
    const arrival = smooth(0.08 + j * 0.024, 0.25 + j * 0.024, u);
    const charge = arrival * (1 - smooth(0.89, 0.96, u));
    ctx.save();
    ctx.translate((j - 1) * 156, -242);
    rr(-34, -30, 68, 60, 12);
    ctx.fillStyle = lane.tint;
    ctx.fill();
    ctx.strokeStyle = '#C4CDDF';
    ctx.lineWidth = 1.7;
    ctx.stroke();

    glyph(j, 0, -4, 1, lane.color, 0.35, true);

    rr(-24, 18, 48, 3.2, 1.6);
    ctx.fillStyle = '#CED7E7';
    ctx.fill();
    if (charge > 0) {
      rr(-24, 18, 48 * charge, 3.2, 1.6);
      ctx.fillStyle = lane.color;
      ctx.fill();
    }
    ctx.restore();
  }

  // Centered Cloud Header Lockup (Sync Icon + Label)
  const headerY = -168;
