    const ny = tx;
    ctx.beginPath();
    ctx.moveTo(ax - tx * 5.2 + nx * 3.4, ay - ty * 5.2 + ny * 3.4);
    ctx.lineTo(ax, ay);
    ctx.lineTo(ax - tx * 5.2 - nx * 3.4, ay - ty * 5.2 - ny * 3.4);
    ctx.strokeStyle = '#6F87AD';
    ctx.lineWidth = 2.2;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
  text('COURSE CLOUD', 14, headerY, 20, ink, 700, 'center');

  // 3. ARCHIVE STORAGE CASE & RECESSED BAYS
