  rr(-357, 156, 714, 219, 19);
  ctx.fillStyle = '#EEF2FA';
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 3.1;
  ctx.stroke();

  for (let j = 0; j < lanes.length; j++) {
    rr(lanes[j].x - 100, 166, 200, 180, 13);
    ctx.fillStyle = '#D7E0EF';
    ctx.fill();
    ctx.strokeStyle = '#B4C2D8';
    ctx.lineWidth = 1.6;
    ctx.stroke();
  }

  // 4. COURSE CARDS (STAGING, CONTENT ASSEMBLY & DOCKING)
  for (let j = 0; j < lanes.length; j++) {
    const lane = lanes[j];
    const form = smooth(0.24 + j * 0.04, 0.31 + j * 0.04, u);
    const parts = smooth(0.30 + j * 0.04, 0.54 + j * 0.04, u);
    const dock = smooth(0.58 + j * 0.035, 0.73 + j * 0.035, u);
    const fadeOut = smooth(0.87 + j * 0.018, 0.94 + j * 0.018, u);
    const opacity = form * (1 - fadeOut);

    if (opacity > 0.001) {
      // Staging center at y = 22 (spans -62..106); Docked center at y = 258 (spans 174..342)
      const cardY = 22 - 14 * (1 - form) + 236 * dock + 12 * fadeOut;

      ctx.save();
      ctx.globalAlpha = opacity;
      ctx.translate(lane.x, cardY);

      // Card body (172 x 168)
      rr(-86, -84, 172, 168, 15);
      ctx.fillStyle = '#FBFCFF';
      ctx.fill();

      // Header band
      ctx.save();
      rr(-86, -84, 172, 168, 15);
      ctx.clip();
      ctx.fillStyle = lane.tint;
      ctx.fillRect(-86, -84, 172, 42);
      ctx.restore();

      rr(-86, -84, 172, 168, 15);
      ctx.strokeStyle = ink;
      ctx.lineWidth = 2.5;
      ctx.stroke();

      line(-85, -42, 85, -42, '#C5CDDE', 1.5);
      text(lane.title, -66, -63, 14, ink, 700, 'left');
      text('0' + (j + 1), 66, -63, 12, lane.color, 600, 'right');

      // Central circular badge & glyph
      ctx.beginPath();
      ctx.arc(0, -4, 29, 0, TAU);
      ctx.fillStyle = lane.tint;
      ctx.fill();
      glyph(j, 0, -4, parts, lane.color, 1, false);

      // Content lines (visible above the front lip even when docked)
      const reveal = smooth(0.15, 0.85, parts);
      if (reveal > 0) {
        rr(-56, 37, 112 * reveal, 4, 2);
        ctx.fillStyle = '#ADBBD1';
        ctx.fill();
        rr(-56, 48, 76 * reveal, 4, 2);
        ctx.fillStyle = '#D0D8E6';
        ctx.fill();
      }

      // Lower progress bar (occluded by the front lip once docked)
      rr(-56, 63, 112, 4, 2);
      ctx.fillStyle = '#DFE5F0';
      ctx.fill();
      if (parts > 0) {
        rr(-56, 63, 112 * parts, 4, 2);
        ctx.fillStyle = lane.color;
        ctx.fill();
        const scan = (0.5 - 0.5 * Math.cos(phase * 4 + j * 0.8)) * 96;
        ctx.save();
        ctx.globalAlpha *= 0.52 * parts;
        rr(-54 + scan, 62, 12, 6, 3);
        ctx.fillStyle = '#FFFFFF';
        ctx.fill();
        ctx.restore();
      }

      ctx.restore();
    }
  }

  // 5. ARCHIVE FRONT LIP & VERIFICATION INDICATORS
  // Intentionally occludes only the lower rim (y = 320..342) of docked cards
  const lipTopY = 320;
  const caseBottomY = 375;
  ctx.save();
  rr(-357, 156, 714, 219, 19);
  ctx.clip();

  const lip = ctx.createLinearGradient(0, lipTopY, 0, caseBottomY);
  lip.addColorStop(0, '#EDF2FA');
  lip.addColorStop(1, '#DEE7F4');
  ctx.fillStyle = lip;
  ctx.fillRect(-357, lipTopY, 714, caseBottomY - lipTopY);
  line(-357, lipTopY, 357, lipTopY, ink, 2.5);

  const lipCenterY = 347.5;
  for (let j = 0; j < lanes.length; j++) {
    const lane = lanes[j];
    const locked = smooth(0.71 + j * 0.035, 0.77 + j * 0.035, u) *
      (1 - smooth(0.88 + j * 0.018, 0.94 + j * 0.018, u));

    text(lane.title, lane.x - 15, lipCenterY, 12, ink, 700, 'center');

    const badgeX = lane.x + 34;
    ctx.beginPath();
    ctx.arc(badgeX, lipCenterY, 9.5, 0, TAU);
    ctx.fillStyle = '#F8FAFE';
    ctx.fill();
    ctx.strokeStyle = '#9DB0CA';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    check(badgeX, lipCenterY, locked, lane.color, 10);

    if (j < 2) {
      line(lane.x + 116, lipTopY + 12, lane.x + 116, caseBottomY - 12, '#B7C5D9', 1.5);
    }
  }
  ctx.restore();

  // Crisp outer contour around the lower archive case lip
  ctx.beginPath();
  ctx.moveTo(-357, lipTopY);
  ctx.lineTo(-357, caseBottomY - 19);
  ctx.quadraticCurveTo(-357, caseBottomY, -338, caseBottomY);
  ctx.lineTo(338, caseBottomY);
  ctx.quadraticCurveTo(357, caseBottomY, 357, caseBottomY - 19);
  ctx.lineTo(357, lipTopY);
  ctx.strokeStyle = ink;
  ctx.lineWidth = 3.1;
  ctx.stroke();

  ctx.restore();
}

