 *   Left column : x -380 .. 180 (width 560), left-aligned, one shared edge
 *   Seal column : centre x 314, outer radius 66 -> right edge exactly at 380
 *   Vertical    : header/footer rows both sit 43 from the inner frame
 *   Rhythm      : proportional vertical spacing across all major groups
 */
var animationConfig = {
  duration: 25, sceneCount: 1, width: 3840, height: 2160, fps: 60,
  bitrate: 100000000, videoBitsPerSecond: 100000000,
  minVideoBitrate: 100000000, loop: true
};

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0)) return;
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const u = sceneProgress;
  const ink = '#283C50';
  const gold = '#B89457';

  // ---- layout constants -------------------------------------------------
  const L = -380;            // shared left edge of all content
  const R = 380;             // shared right edge of all content
  const colW = 560;          // left column width (L .. L+colW)
  const sealX = 314, sealY = -18;
  const headerY = -241, footerY = 241;

  function smooth(a, b, value) {
    const x = Math.max(0, Math.min(1, (value - a) / (b - a)));
    return x * x * x * (x * (x * 6 - 15) + 10);
  }
  function windowEnv(inA, inB, outA, outB, value) {
    return smooth(inA, inB, value) * (1 - smooth(outA, outB, value));
  }
  function rr(x, y, w, h, r) {
    if (w <= 0 || h <= 0) return;
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
