    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function line(points, color, lw, alpha) {
    ctx.save(); if (alpha !== undefined) ctx.globalAlpha *= alpha;
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color; ctx.lineWidth = lw || 2; ctx.stroke(); ctx.restore();
  }
  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function text(s, x, y, size, color, weight, align) {
    const fontWeight = weight >= 650 ? 700 : weight >= 550 ? 600 : 500;
    ctx.font = fontWeight + ' ' + size + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color; ctx.fillText(s, x, y);
  }
  function check(x, y, size, p, color) {
    const v = clamp(p), a = .42;
    if (v <= 0) return;
    const pts = [[x - size * .45, y], [x - size * .1, y + size * .3], [x + size * .5, y - size * .36]];
    ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
    if (v < a) ctx.lineTo(mix(pts[0][0], pts[1][0], v / a), mix(pts[0][1], pts[1][1], v / a));
    else {
      ctx.lineTo(pts[1][0], pts[1][1]);
      ctx.lineTo(mix(pts[1][0], pts[2][0], (v - a) / (1 - a)), mix(pts[1][1], pts[2][1], (v - a) / (1 - a)));
    }
    ctx.strokeStyle = color; ctx.lineWidth = 2.2; ctx.stroke();
  }
  function glyph(id, x, y, size, color) {
    ctx.save(); ctx.translate(x, y); ctx.scale(size / 40, size / 40);
    if (id === 0) {
      ctx.beginPath(); ctx.moveTo(0, -10);
      ctx.quadraticCurveTo(-9, -17, -18, -12); ctx.lineTo(-18, 14);
      ctx.quadraticCurveTo(-9, 9, 0, 15); ctx.quadraticCurveTo(9, 9, 18, 14);
      ctx.lineTo(18, -12); ctx.quadraticCurveTo(9, -17, 0, -10); ctx.closePath();
      ctx.strokeStyle = color; ctx.lineWidth = 2.6; ctx.stroke();
      line([[0, -10], [0, 15]], color, 2);
      line([[-12, -4], [-6, -3]], color, 1.8); line([[6, -3], [12, -4]], color, 1.8);
    } else if (id === 1) {
      for (let j = 0; j < 4; j++) box((j % 2) * 19 - 17, Math.floor(j / 2) * 19 - 17, 14, 14, 3, null, color, 2.3);
    } else {
      line([[-17, 17], [18, 17]], color, 2.1);
      for (let j = 0; j < 3; j++) box(-13 + j * 11, 11 - (j + 1) * 8, 6, (j + 1) * 8, 2, color, null);
    }
    ctx.restore();
  }

  // Rounded route: left along the bank, up the clear transit lane, then right
  // into the assigned slot. Sampling by arc length preserves a coherent speed
  // through both corners. Earlier answers remain outside every later route.
  function tilePosition(id, p) {
    const x0 = sourceXs[id], y0 = 178, lane = 112, y1 = slotYs[id], x1 = 200, r = 20;
    const lens = [x0 - lane - r, r * Math.PI / 2, y0 - y1 - 2 * r, r * Math.PI / 2, x1 - lane - r];
    let distance = clamp(p) * lens.reduce(function (sum, n) { return sum + n; }, 0);
    if (distance <= lens[0]) return [x0 - distance, y0];
    distance -= lens[0];
    if (distance <= lens[1]) {
      const a = Math.PI / 2 + distance / r;
      return [lane + r + Math.cos(a) * r, y0 - r + Math.sin(a) * r];
    }
    distance -= lens[1];
    if (distance <= lens[2]) return [lane, y0 - r - distance];
    distance -= lens[2];
    if (distance <= lens[3]) {
      const a = Math.PI + distance / r;
      return [lane + r + Math.cos(a) * r, y1 + r + Math.sin(a) * r];
    }
    distance -= lens[3];
    return [lane + r + Math.min(lens[4], distance), y1];
  }

  function leftContent(q, offset) {
    ctx.save(); rrPath(-490, -174, 438, 389, 6); ctx.clip(); ctx.translate(offset, 0);
    box(-474, -158, 406, 173, 14, '#EDF5F1', '#D6E5DE', 1.5);
    text('EXPLORE THE IDEA', -454, -133, 11, C.muted, 750);
    const xs = [-404, -270, -136];
    for (let j = 0; j < 2; j++) {
      const x1 = xs[j] + 34, x2 = xs[j + 1] - 34;
      line([[x1, -54], [x2, -54]], '#ACBFBA', 2);
      line([[x2 - 5, -58], [x2, -54], [x2 - 5, -50]], '#ACBFBA', 1.7);
      const v = ((sceneProgress * 3 - j * .33) % 1 + 1) % 1;
      ctx.save(); ctx.globalAlpha *= Math.pow(Math.sin(v * Math.PI), 2);
      circle(mix(x1 + 6, x2 - 6, v), -54, 3.5, accents[j]); ctx.restore();
    }
    for (let j = 0; j < 3; j++) {
      box(xs[j] - 32, -86, 64, 64, 11, '#FFFFFF', accents[j], 2.1);
      if (j === 1) {
        ctx.save(); ctx.translate(xs[j], -54); ctx.rotate(phase * 2);
        glyph(j, 0, 0, 32, accents[j]); ctx.restore();
      } else if (j === 2) {
        line([[xs[j] - 19, -34], [xs[j] + 19, -34]], accents[j], 1.7);
        for (let k = 0; k < 3; k++) {
          const h = 10 + k * 6 + 3 * Math.sin(phase * 3 + k);
          box(xs[j] - 15 + k * 12, -40 - h, 7, h, 2, accents[j], null);
        }
      } else glyph(j, xs[j], -54, 34, accents[j]);
      text(['READ', 'CONNECT', 'APPLY'][j], xs[j], 0, 9, C.muted, 750, 'center');
    }

    const starts = [.04, .20, .36], ends = [.18, .34, .50];
    const widths = [346, 318, 335], ys = [60, 103, 146];
    for (let j = 0; j < 3; j++) {
      const p = smooth(starts[j], ends[j], q), y = ys[j];
      line([[-466, y], [-466 + widths[j], y]], '#AABFBA', 5.5);
      line([[-466, y + 13], [-466 + widths[j] * .76, y + 13]], '#D2DFD8', 4);
      if (p > 0) line([[-466, y + 25], [-466 + widths[j] * p, y + 25]], accents[j], 3.6);
      // Small reading marker travels only inside its reserved underline lane.
      const alpha = smooth(starts[j], starts[j] + .02, q) * (1 - smooth(ends[j] - .02, ends[j], q));
      ctx.save(); ctx.globalAlpha *= alpha;
      const mx = -466 + widths[j] * p;
      box(mx + 7, y + 21, 25, 8, 3, '#FFFFFF', accents[j], 1.7);
      ctx.beginPath(); ctx.moveTo(mx + 1, y + 25); ctx.lineTo(mx + 7, y + 22); ctx.lineTo(mx + 7, y + 28); ctx.closePath();
      ctx.fillStyle = accents[j]; ctx.fill(); ctx.restore();
    }
    ctx.restore();
  }

  function rightContent(q, offset) {
    ctx.save(); rrPath(52, -174, 438, 389, 6); ctx.clip(); ctx.translate(offset, 0);
    line([[112, 178], [112, -100]], '#CFDED9', 1.7);
    for (let j = 0; j < 3; j++) {
      const done = smooth(moveEnds[j], moveEnds[j] + .025, q);
      line([[112, slotYs[j]], [151, slotYs[j]]], '#CFDED9', 1.7);
      circle(112, slotYs[j], 3, '#B7CDC5');
      box(154, slotYs[j] - 32, 300, 64, 11, mixColor('#F1F7F2', accents[j], done * .05), '#CCDED5', 1.5);
      ctx.save(); ctx.setLineDash([4, 5]);
      box(164, slotYs[j] - 27, 72, 54, 9, '#F9FCF8', '#BCCFC7', 1.5); ctx.restore();
      text(['FOUNDATION', 'CONNECTION', 'APPLICATION'][j], 254, slotYs[j] - 4, 10, C.ink, 750);
      line([[254, slotYs[j] + 10], [j === 1 ? 359 : 372, slotYs[j] + 10]], '#C4D5CD', 3);
      circle(433, slotYs[j], 8, mixColor('#E1EBE5', accents[j], done * .1), mixColor('#C6D8CF', accents[j], done), 1.4);
      check(433, slotYs[j], 9, done, accents[j]);
    }
    text('PRACTICE TILES', 157, 136, 10, C.muted, 750);
    // Empty bank wells remain fixed while their corresponding tiles travel.
    for (let j = 0; j < 3; j++) {
      box(sourceXs[j] - 38, 149, 76, 58, 10, '#EEF5EF', '#D5E2DA', 1.3);
      line([[sourceXs[j] - 11, 178], [sourceXs[j] + 11, 178]], '#CBDCD2', 2);
    }
    for (let j = 0; j < 3; j++) {
      const p = smooth(moveStarts[j], moveEnds[j], q);
      const pos = tilePosition(j, p);
      box(pos[0] - 36, pos[1] - 27, 72, 54, 9, mixColor('#FFFFFF', accents[j], .09), accents[j], 2.1);
      glyph(j, pos[0], pos[1], 30, accents[j]);
    }
    ctx.restore();
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowColor = 'transparent';
  ctx.filter = 'none';
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
  const bg = ctx.createLinearGradient(0, height, width, 0);
  bg.addColorStop(0, '#DCECE5'); bg.addColorStop(.52, '#EEF3ED'); bg.addColorStop(1, '#DDE6F0');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);
  ctx.beginPath(); ctx.moveTo(0, height * .16);
  ctx.bezierCurveTo(width * .23, height * .42, width * .29, height * .04, width * .56, 0);
  ctx.lineTo(0, 0); ctx.closePath(); ctx.fillStyle = 'rgba(162,190,185,0.10)'; ctx.fill();
  ctx.beginPath(); ctx.moveTo(width * .58, height);
  ctx.bezierCurveTo(width * .78, height * .69, width * .88, height * .85, width, height * .58);
  ctx.lineTo(width, height); ctx.closePath(); ctx.fillStyle = 'rgba(149,174,193,0.09)'; ctx.fill();

  ctx.translate(width / 2, height * .51); ctx.scale(scale, scale);
  line([[-604, 317], [-565, 317]], '#A6BFBC', 2);
  line([[-546, 317], [546, 317]], '#A6BFBC', 2);
  line([[565, 317], [604, 317]], '#A6BFBC', 2);

  // Flat vector cover and two mirrored page outlines; no perspective transform.
  ctx.beginPath(); ctx.moveTo(-548, -260);
  ctx.quadraticCurveTo(-292, -294, -12, -257); ctx.quadraticCurveTo(0, -253, 12, -257);
  ctx.quadraticCurveTo(292, -294, 548, -260); ctx.lineTo(548, 257);
  ctx.quadraticCurveTo(292, 229, 12, 269); ctx.quadraticCurveTo(0, 275, -12, 269);
  ctx.quadraticCurveTo(-292, 229, -548, 257); ctx.closePath();
  ctx.fillStyle = '#A8C7C1'; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 3.6; ctx.stroke();

  ctx.beginPath(); ctx.moveTo(-532, -251); ctx.quadraticCurveTo(-274, -279, -14, -244);
  ctx.lineTo(-14, 251); ctx.quadraticCurveTo(-274, 220, -532, 247); ctx.closePath();
  ctx.fillStyle = C.paper; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.6; ctx.stroke();
  ctx.beginPath(); ctx.moveTo(14, -244); ctx.quadraticCurveTo(274, -279, 532, -251);
  ctx.lineTo(532, 247); ctx.quadraticCurveTo(274, 220, 14, 251); ctx.closePath();
  ctx.fillStyle = '#F8FCF6'; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.6; ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-14, -244); ctx.quadraticCurveTo(0, -231, 14, -244);
  ctx.lineTo(14, 251); ctx.quadraticCurveTo(0, 263, -14, 251); ctx.closePath();
  ctx.fillStyle = '#D5E6DD'; ctx.fill();
  line([[0, -227], [0, 246]], '#A3C2B6', 1.5);

  text('LEARN', -466, -217, 21, C.ink, 750);
  text('DIGITAL WORKBOOK', -465, -197, 10, C.muted, 650);
  text('PRACTICE', 82, -217, 21, C.ink, 750);
  text('BUILD THE SEQUENCE', 83, -197, 10, C.muted, 650);
  line([[-490, -183], [-52, -183]], '#D3E1D8', 1.5);
  line([[52, -183], [393, -183]], '#D3E1D8', 1.5);

  const feed = smooth(.835, 1, u);
  const pageWidth = 454;
  leftContent(u, -pageWidth * feed);
  rightContent(u, -pageWidth * feed);
  if (feed > 0) {
    leftContent(0, pageWidth * (1 - feed));
    rightContent(0, pageWidth * (1 - feed));
  }

  const bookmarkDrop = 7 * smooth(.75, .835, u) * (1 - smooth(.90, 1, u));
  ctx.beginPath(); ctx.moveTo(416, -269 + bookmarkDrop); ctx.lineTo(450, -269 + bookmarkDrop);
  ctx.lineTo(450, -178 + bookmarkDrop); ctx.lineTo(433, -189 + bookmarkDrop);
  ctx.lineTo(416, -178 + bookmarkDrop); ctx.closePath();
  ctx.fillStyle = C.coral; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2; ctx.stroke();
  line([[424, -256 + bookmarkDrop], [442, -256 + bookmarkDrop]], '#F1C2AE', 2);
  text('01', -281, 225, 11, C.muted, 650, 'center');
  text('02', 281, 225, 11, C.muted, 650, 'center');
  ctx.restore();
}

